-- P13c-3b-1b-2b-1. Generated by scripts/generate-source-witness-migration.mjs.
-- Keep migration 0006, old blob bytes/FKs and birth metadata unchanged.
-- Rust performs bounded original provenance backfill in this same migration TX.
CREATE TABLE confirmation_source_witnesses (
    witness_sha256 TEXT NOT NULL CHECK (typeof(witness_sha256) = 'text' AND length(witness_sha256) = 64 AND length(CAST(witness_sha256 AS BLOB)) = 64 AND witness_sha256 NOT GLOB '*[^0-9a-f]*') PRIMARY KEY,
    byte_length INTEGER NOT NULL CHECK (typeof(byte_length) = 'integer' AND byte_length BETWEEN 1 AND 8388608),
    content_bytes BLOB NOT NULL CHECK (typeof(content_bytes) = 'blob' AND length(content_bytes) = byte_length),
    recorded_at TEXT NOT NULL CHECK (typeof(recorded_at) = 'text')
);
CREATE TRIGGER confirmation_source_witnesses_no_update BEFORE UPDATE ON confirmation_source_witnesses
BEGIN SELECT RAISE(ABORT, 'confirmation_source_witnesses is append-only'); END;
CREATE TRIGGER confirmation_source_witnesses_no_delete BEFORE DELETE ON confirmation_source_witnesses
BEGIN SELECT RAISE(ABORT, 'confirmation_source_witnesses is append-only'); END;
CREATE TRIGGER confirmation_source_witnesses_no_replacement BEFORE INSERT ON confirmation_source_witnesses
WHEN EXISTS (SELECT 1 FROM confirmation_source_witnesses WHERE witness_sha256 = NEW.witness_sha256 AND NOT (witness_sha256 IS NEW.witness_sha256 AND byte_length IS NEW.byte_length AND content_bytes IS NEW.content_bytes AND recorded_at IS NEW.recorded_at))
BEGIN SELECT RAISE(ABORT, 'confirmation_source_witnesses is append-only'); END;

-- A digest has exactly one logical blob kind across both physical tables.
CREATE TRIGGER confirmation_source_witnesses_blob_namespace BEFORE INSERT ON confirmation_source_witnesses
WHEN EXISTS (SELECT 1 FROM confirmation_blobs WHERE blob_sha256 = NEW.witness_sha256)
BEGIN SELECT RAISE(ABORT, 'confirmation blob namespace collision'); END;
CREATE TRIGGER confirmation_blobs_witness_namespace BEFORE INSERT ON confirmation_blobs
WHEN EXISTS (SELECT 1 FROM confirmation_source_witnesses WHERE witness_sha256 = NEW.blob_sha256)
BEGIN SELECT RAISE(ABORT, 'confirmation blob namespace collision'); END;

-- Only replace the eight old joint capacity triggers. Interval/unknown caps
-- and all original append-only/FK/domain guards remain in force.
DROP TRIGGER confirmation_batches_capacity;
DROP TRIGGER confirmation_selections_capacity;
DROP TRIGGER confirmation_operations_capacity;
DROP TRIGGER confirmation_exposures_capacity;
DROP TRIGGER confirmation_admissions_capacity;
DROP TRIGGER confirmation_events_capacity;
DROP TRIGGER confirmation_blobs_capacity;
DROP TRIGGER confirmation_conflicts_capacity;

CREATE TRIGGER confirmation_batches_capacity BEFORE INSERT ON confirmation_batches
WHEN NOT EXISTS (SELECT 1 FROM confirmation_batches WHERE batch_id = NEW.batch_id)
 AND (((SELECT COUNT(*) FROM confirmation_batches) + (SELECT COUNT(*) FROM confirmation_selections) + (SELECT COUNT(*) FROM confirmation_operations) + (SELECT COUNT(*) FROM confirmation_exposures) + (SELECT COUNT(*) FROM confirmation_admissions) + (SELECT COUNT(*) FROM confirmation_events) + (SELECT COUNT(*) FROM confirmation_blobs) + (SELECT COUNT(*) FROM confirmation_conflicts) + (SELECT COUNT(*) FROM confirmation_source_witnesses)) >= 10000 OR ((SELECT COALESCE(SUM(length(CAST(document_json AS BLOB))),0) FROM confirmation_batches) + (SELECT COALESCE(SUM(length(CAST(document_json AS BLOB))),0) FROM confirmation_selections) + (SELECT COALESCE(SUM(length(CAST(document_json AS BLOB))),0) FROM confirmation_operations) + (SELECT COALESCE(SUM(length(CAST(document_json AS BLOB))),0) FROM confirmation_exposures) + (SELECT COALESCE(SUM(length(CAST(document_json AS BLOB))),0) FROM confirmation_admissions) + (SELECT COALESCE(SUM(length(CAST(document_json AS BLOB))),0) FROM confirmation_events) + (SELECT COALESCE(SUM(length(content_bytes)),0) FROM confirmation_blobs) + (SELECT COALESCE(SUM(length(CAST(document_json AS BLOB))),0) FROM confirmation_conflicts) + (SELECT COALESCE(SUM(length(content_bytes)),0) FROM confirmation_source_witnesses)) + length(CAST(NEW.document_json AS BLOB)) > 67108864)
BEGIN SELECT RAISE(ABORT, 'confirmation history capacity exceeded'); END;

